#include <iostream>
#include <vector>

int main()
{
    int S{}, K{};
    if (!(std::cin >> S >> K)) return 0;

    std::vector<int> outOf(static_cast<std::size_t>(S), 0);
    for (int i = 0; i < S; ++i) std::cin >> outOf[static_cast<std::size_t>(i)];

    std::vector<std::vector<int>> next(static_cast<std::size_t>(S),
                                       std::vector<int>(static_cast<std::size_t>(K), 0));
    for (int i = 0; i < S; ++i)
        for (int j = 0; j < K; ++j)
            std::cin >> next[static_cast<std::size_t>(i)][static_cast<std::size_t>(j)];

    int n{};
    std::cin >> n;

    std::vector<int> states;
    states.push_back(0);
    int s{ 0 };
    for (int i = 0; i < n; ++i)
    {
        int c{};
        std::cin >> c;
        s = next[static_cast<std::size_t>(s)][static_cast<std::size_t>(c)];
        states.push_back(s);
    }

    std::cout << "states";
    for (int x : states) std::cout << ' ' << x;
    std::cout << "\n";

    std::cout << "outputs";
    for (int x : states) std::cout << ' ' << outOf[static_cast<std::size_t>(x)];
    std::cout << "\n";

    int ones{ 0 };
    long long first{ -1 };
    for (std::size_t i = 0; i < states.size(); ++i)
    {
        int o{ outOf[static_cast<std::size_t>(states[i])] };
        if (o == 1)
        {
            ++ones;
            if (first < 0) first = static_cast<long long>(i);
        }
    }

    std::cout << "ones " << ones << "\n";
    if (first < 0) std::cout << "first-one none\n";
    else           std::cout << "first-one " << first << "\n";

    return 0;
}
